async def sub_query_strict(prompt, validate_regex=None, max_retries=3):
    for attempt in range(max_retries):
        result = await sub_query(prompt)
        if validate_regex and not re.search(validate_regex, result):
            prompt = f"{prompt}\n\nPrevious attempt was invalid. Must match: {validate_regex}\nPrevious output: {result[:200]}"
